"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[86],{70086:a=>{a.exports=JSON.parse('{"slug":"ssha-otlozhili-poshliny-pokupatelyam-rossiyskoy-nefti","locale":"ru","title":"США отложили пошлины для покупателей российской нефти, акции за неделю выросли на 4,5%","description":"США приостановили пошлины до 100% против крупнейших покупателей российской нефти и газа. Как работают вторичные пошлины и что пауза значит для России.","blocks":[{"id":"b001","kind":"paragraph","text":"18 сентября президент США Дональд Трамп подписал закон о санкциях против России, который продвигал сенатор Линдси Грэм. Закон разрешал вводить пошлины до 100% на все товары, которые ввозят в США из 5 стран, больше всех покупающих российскую нефть и газ. Меры должны были заработать 18 октября. За 2 дня до этого Трамп подписал указ, который их приостановил. Закон это допускает, если президент сообщит Конгрессу, что меры против интересов США."},{"id":"b002","kind":"paragraph","text":"Госсекретарь Марко Рубио объяснил паузу двумя причинами. Администрация не хочет сорвать переговоры с Россией и Украиной и за 60 дней посчитает, что пошлины сделают с мировой экономикой. Они ударили бы по Индии и Китаю, а нефти на рынке и так не хватает из-за перебоев в Ормузском проливе. 16 октября Brent поднималась до $110 за баррель, максимума с мая. Аналитики связывают паузу и с выборами в Конгресс 3 ноября: дорогое топливо в США бьёт по избирателям."},{"id":"b003","kind":"paragraph","text":"Представим рынок, где управляющая компания штрафует всех, кто покупает овощи у одного фермера. Штраф платит покупатель, но теряет и фермер. Чтобы удержать клиентов, ему придётся снижать цену или искать тех, кому штраф не страшен. Так устроены вторичные пошлины. В сентябре Китай купил российской нефти, газа и угля примерно на 9,1 млрд евро, Индия на 4,1 млрд. Пошлина до 100% на весь их экспорт в США заставила бы их выбирать между российской нефтью и американским рынком или требовать большую скидку."},{"id":"b004","kind":"paragraph","text":"Скидка к мировой цене определяет, сколько Россия получает за каждый баррель. В сентябре нефть Urals стоила в среднем $92,08 за баррель. Индия уже переключается на других поставщиков: доля российской нефти в её импорте снизилась с 51% в июле до 44% в августе, закупки сместились к нефти из США и ОАЭ. Пауза снимает угрозу, что покупатели уйдут или потребуют большую скидку, но только на время."},{"id":"b005","kind":"paragraph","text":"Инвесторы восприняли паузу как шанс на смягчение санкций, акции поддержала и дорогая нефть. Индекс Мосбиржи с 12 по 16 октября вырос на 4,51%, до 2426 пунктов, а в воскресенье, 18 октября, на торгах выходного дня поднимался почти до 2450, максимума за 3 месяца. Рубль укрепился скромнее: официальный курс доллара на 17–19 октября 83,62 рубля против 84,90 неделей раньше. Brent утром 19 октября подешевела на 2%, до $107,6: рынок ждёт, что российского топлива в мире станет больше."},{"id":"b006","kind":"paragraph","text":"Указ не отменяет закон. Президент может вернуть пошлины в любой момент, а окончательное решение ждут после выборов 3 ноября и декабрьского саммита G20 в Майами. Отказ от пошлин сохранит нынешних покупателей и нынешний размер скидки. Их введение заставит Индию и Китай пересчитать закупки, и тогда давление ляжет на экспортную выручку и бюджет. Рост акций за неделю во многом отражает надежду на первый вариант, которая пока ничем не закреплена."},{"id":"b007","kind":"heading","text":"Какие пошлины против покупателей российской нефти отложили США?"},{"id":"b008","kind":"paragraph","text":"Закон, подписанный 18 сентября 2026 года, разрешал с 18 октября вводить пошлины до 100% на все товары, которые ввозят в США из 5 стран, больше всех покупающих российскую нефть и газ. 16 октября президент США приостановил эти меры указом."},{"id":"b009","kind":"heading","text":"Как пошлины против Индии и Китая бьют по России?"},{"id":"b010","kind":"paragraph","text":"Покупателю приходится выбирать между российской нефтью и американским рынком для своих товаров. Чтобы удержать клиентов, продавец снижает цену. Для России это означает большую скидку к мировой цене и меньшую выручку с каждого барреля."},{"id":"b011","kind":"heading","text":"Когда США примут окончательное решение?"},{"id":"b012","kind":"paragraph","text":"Госсекретарь Марко Рубио назвал срок до 60 дней. Решение ждут после выборов в Конгресс США 3 ноября и декабрьского саммита G20 в Майами. Указ не отменяет закон, и президент может вернуть пошлины в любой момент."}],"sources":[{"label":"Trump Signs Order Exempting Russia From New Sanctions Legislation","url":"https://www.themoscowtimes.com/2026/10/17/trump-signs-order-exempting-russia-from-new-sanctions-legislation-a94012"},{"label":"Trump Suspends Russia-Linked Tariffs, Offering Relief To India","url":"https://www.outlookindia.com/international/trump-suspends-russia-linked-tariffs-india-russian-oil"},{"label":"What Trump\'s Waiver of New Russia Sanctions Means for Ukraine","url":"https://time.com/article/2026/10/17/what-trump-s-waiver-of-new-russia-sanctions-means-for-ukraine/"},{"label":"Трамп отложил \xabадские санкции\xbb","url":"https://www.kommersant.ru/doc/9041600"},{"label":"Oil slips from 5-month high as Trump\'s Russia sanctions waiver may bring more supplies","url":"https://www.brecorder.com/news/40444883/oil-slips-from-5-month-high-as-trumps-russia-sanctions-waiver-may-bring-more-supplies"},{"label":"September 2026 — Monthly analysis of Russian fossil fuel exports and sanctions","url":"https://energyandcleanair.org/september-2026-monthly-analysis-of-russian-fossil-fuel-exports-and-sanctions/"},{"label":"Российская нефть подорожала почти в полтора раза","url":"https://lenta.ru/news/2026/10/05/urals/"},{"label":"Индекс Мосбиржи прибавил 25% за три месяца","url":"https://www.vbr.ru/novosti/investicii/2026/10/19/indeks-mosbirji-pribavil-25-za-tri-mesyaca/"},{"label":"ЦБ понизил курс доллара на 17–19 октября до 83,62 рубля","url":"https://finance.rambler.ru/economics/57237637-tsb-ponizil-kurs-dollara-na-17-19-oktyabrya-do-83-62-rublya/"},{"label":"Курс доллара США на 10 октября 2026 года","url":"https://ppt.ru/currencies/usd/10-10-2026"}],"sourceBodySha256":"08a9ef35b4b6638b9180eb959dc7416a99027fabfd65ad99f9ce3dbcf52878d0"}')}}]);